module benchmark/solution

import std/io (readFile, writeFile, println)
import std/json (decode, Json, JNull, JString, JNumber, JObject, JArray)
import std/result (Result, Ok, Err)

-- Config record type
type Config = {
  app_name: string,
  version: string,
  port: int,
  features: List[string]
}

-- Custom error type for loadConfig
type ConfigError =
  | FileReadError(string)
  | JsonParseError(string)
  | InvalidConfigFormat(string)
  | ValidationError(string)

-- Helper to validate port range
func validatePort(port: int) -> bool =
  port >= 1024 && port <= 65535

-- Helper to count occurrences of a character in a string
func countChar(s: string, char_to_find: string) -> int =
  let len_s = _str_len(s) in
  letrec loop = \idx. \count.
    if idx >= len_s
    then count
    else
      let current_char = _str_at(s, idx) in
      if _str_eq(current_char, char_to_find)
      then loop(idx + 1)(count + 1)
      else loop(idx + 1)(count)
  in loop(0)(0)

-- Helper to validate version format (contains two dots)
func validateVersion(ver: string) -> bool =
  _str_len(ver) > 0 && countChar(ver, ".") == 2

-- Helper to extract field from JSON object.
-- Returns JNull if the input Json is not a JObject or if the target_key is not found.
func getField(json: Json, target_key: string) -> Json =
  match json {
    JObject(kvs) =>
      letrec findKeyInList = \kvs_list.
        match kvs_list {
          [] => JNull,
          ::(kv, rest) => if _str_eq(kv.key, target_key) then kv.value else findKeyInList(rest)
        }
      in findKeyInList(kvs),
    _ => JNull -- Not a JObject
  }

-- Helper to convert JArray[Json] to List[string].
-- Returns Err if any element is not a JString or if the input is not a JArray.
func jsonArrayToStringList(json_array: Json) -> Result[List[string], string] =
  match json_array {
    JArray(elements) =>
      letrec convertElements = \elems.
        match elems {
          [] => Ok([]),
          ::(head, tail) =>
            match head {
              JString(s) =>
                match convertElements(tail) {
                  Ok(rest_list) => Ok(::(s, rest_list)),
                  Err(msg) => Err(msg) -- Propagate error from recursive call
                },
              _ => Err("Feature list contains non-string elements (found non-JString)")
            }
        }
      in convertElements(elements),
    _ => Err("Expected JSON array for features (found non-JArray)")
  }

-- Helper to get length of a list (polymorphic)
func length[a](xs: List[a]) -> int =
  match xs {
    [] => 0,
    ::(_, rest) => 1 + length(rest)
  }

-- Loads and validates configuration from a JSON file.
func loadConfig(filename: string) -> Result[Config, ConfigError] ! {FS} {
  let content_result = readFile(filename);
  match content_result {
    Ok(content) =>
      match decode(content) {
        Ok(json_data) =>
          match json_data {
            JObject(kvs) =>
              -- Extract fields using getField, which returns JNull if not found/wrong type
              let app_name_json = getField(json_data, "app_name") in
              let version_json = getField(json_data, "version") in
              let port_json = getField(json_data, "port") in
              let features_json = getField(json_data, "features") in

              -- Validate types and extract values through nested pattern matching
              match app_name_json {
                JString(app_name_val) =>
                  match version_json {
                    JString(version_val) =>
                      match port_json {
                        JNumber(port_float) =>
                          let port_val = floatToInt(port_float) in
                          match jsonArrayToStringList(features_json) {
                            Ok(features_val) =>
                              -- Perform value-based validations
                              let port_valid = validatePort(port_val) in
                              let version_valid = validateVersion(version_val) in
                              let features_not_empty = length(features_val) > 0 in

                              if port_valid && version_valid && features_not_empty
                              then Ok({ app_name: app_name_val, version: version_val, port: port_val, features: features_val })
                              else
                                Err(ValidationError(
                                  (if not port_valid then "Invalid port range. " else "") ++
                                  (if not version_valid then "Invalid version format. " else "") ++
                                  (if not features_not_empty then "Features list cannot be empty." else "")
                                ))
                            Err(msg) => Err(InvalidConfigFormat("Features field error: " ++ msg))
                          }
                        _ => Err(InvalidConfigFormat("Port field must be a number (or is missing)."))
                      }
                    _ => Err(InvalidConfigFormat("Version field must be a string (or is missing)."))
                  }
                _ => Err(InvalidConfigFormat("App_name field must be a string (or is missing)."))
              }
            _ => Err(InvalidConfigFormat("Config file root must be a JSON object."))
          },
        Err(msg) => Err(JsonParseError("Failed to parse JSON content: " ++ msg))
      },
    Err(msg) => Err(FileReadError("Failed to read config file: " ++ msg))
  }
}

-- Main function to create the config file, load it, validate, and print results.
export func main() -> () ! {IO, FS} {
  -- Create config file
  let configJsonContent = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  let writeResult = writeFile("app_config.json", configJsonContent);
  match writeResult {
    Ok(_) => (), -- File written successfully
    Err(msg) => { println("Error writing config file: " ++ msg); () } -- Print error and return unit
  };

  -- Load and validate config
  match loadConfig("app_config.json") {
    Ok(config) =>
      let numFeatures = length(config.features) in
      println("Loaded " ++ config.app_name ++ " v" ++ config.version ++ " on port " ++ show(config.port) ++ " with " ++ show(numFeatures) ++ " features"),
    Err(FileReadError(msg)) => println("Configuration file read error: " ++ msg),
    Err(JsonParseError(msg)) => println("Configuration JSON parse error: " ++ msg),
    Err(InvalidConfigFormat(msg)) => println("Invalid configuration format: " ++ msg),
    Err(ValidationError(msg)) => println("Configuration validation error: " ++ msg)
  }
}

