import std/io (println, readFile, writeFile)
import std/json (encode, jo, kv, js, jnum, ja)
import std/option (Option, Some, None)
import std/numeric (_str_to_int, intToFloat)
import std/string (split, len, contains, eq)

-- Helper to filter a list based on a predicate
func filter[a](pred: a -> bool, xs: List[a]) -> List[a] {
  match xs {
    [] => [],
    ::(x, rest) =>
      if pred(x)
      then ::(x, filter(pred, rest))
      else filter(pred, rest)
  }
}

-- Helper to map a function over a list
func map[a, b](f: a -> b, xs: List[a]) -> List[b] {
  match xs {
    [] => [],
    ::(x, rest) => ::(f(x), map(f, rest))
  }
}

-- Basic foldl for lists
func foldl[a, b](f: b -> a -> b, acc: b, xs: List[a]) -> b {
  match xs {
    [] => acc,
    ::(x, rest) => foldl(f, f(acc)(x), rest)
  }
}

-- Reverse list (needed for foldl to maintain original order if prepending)
func reverse[a](xs: List[a]) -> List[a] {
  letrec rev_acc = \current. \acc.
    match current {
      [] => acc,
      ::(h, t) => rev_acc(t)(::(h, acc))
    } in
  rev_acc(xs)([])
}

-- Helper to split string by delimiter and remove empty strings
func splitAndFilterEmpty(s: string, delim: string) -> List[string] {
  let parts = split(s, delim);
  let filterEmpty = \x. len(x) > 0;
  filter(filterEmpty, parts)
}

-- Helper to parse age from string, ensuring it's a positive integer
func parseAge(s: string) -> Option[int] {
  match _str_to_int(s) {
    Some(age) => if age > 0 then Some(age) else None,
    None => None
  }
}

-- Helper to validate email format (contains '@')
func validateEmail(email: string) -> bool {
  contains(email, "@")
}

-- User record type for structured data
type User = {name: string, age: int, email: string}

export func main() -> () ! {IO, FS} {
  -- 1. Create users.csv
  let csvContent = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nInvalidAge,0,invalid@email.com\nCarol,35,carol@example.com\nInvalidEmail,22,invalid-email\n" in
  let writeCsvResult = writeFile("users.csv", csvContent);
  match writeCsvResult {
    Ok(_) => (),
    Err(msg) => println("Error writing users.csv: " ++ msg)
  };

  -- 2. Read and parse CSV
  match readFile("users.csv") {
    Ok(fileContent) => {
      let lines = splitAndFilterEmpty(fileContent, "\n");
      match lines {
        [] => println("CSV file is empty."),
        ::(headerLine, dataLines) => {
          let headers = splitAndFilterEmpty(headerLine, ",");
          if eq(headers.0, "name") && eq(headers.1, "age") && eq(headers.2, "email")
          then (
            let processRow = \rowStr.
              let values = splitAndFilterEmpty(rowStr, ",");
              match values {
                ::(name, ::(ageStr, ::(email, []))) =>
                  match parseAge(ageStr) {
                    Some(age) =>
                      if validateEmail(email)
                      then Some({name: name, age: age, email: email})
                      else None,
                    None => None
                  },
                _ => None -- Invalid number of columns
              }
            in

            -- Accumulator function for foldl
            let usersBuilder = \acc. \rowStr.
              match processRow(rowStr) {
                Some(user) => ::(user, acc),
                None => acc
              }
            in

            let usersReversed = foldl(usersBuilder, [], dataLines);
            let finalValidatedUsers = reverse(usersReversed);
            let validRowCount = length(finalValidatedUsers);

            -- 3. Convert to JSON
            let usersToJson = \user.
              jo([
                kv("name", js(user.name)),
                kv("age", jnum(intToFloat(user.age))),
                kv("email", js(user.email))
              ])
            in
            let jsonUserObjects = map(usersToJson, finalValidatedUsers);
            let finalJson = encode(ja(jsonUserObjects));

            -- 4. Write users.json
            let writeJsonResult = writeFile("users.json", finalJson);
            match writeJsonResult {
              Ok(_) => println("Converted " ++ show(validRowCount) ++ " valid rows to users.json"),
              Err(msg) => println("Error writing users.json: " ++ msg)
            }
          )
          else println("CSV headers do not match expected: name,age,email. Got: " ++ show(headers))
        }
      }
    },
    Err(msg) => println("Error reading users.csv: " ++ msg)
  }
}

