import csv
import json
from pathlib import Path


def validate_email(email: str) -> bool:
    """Validate email contains @ symbol."""
    return "@" in email


def validate_age(age_str: str) -> bool:
    """Validate age is a positive integer."""
    try:
        age = int(age_str)
        return age > 0
    except ValueError:
        return False


def parse_age(age_str: str) -> int | None:
    """Parse age string to integer."""
    try:
        age = int(age_str)
        return age if age > 0 else None
    except ValueError:
        return None


def csv_to_json(csv_file: str, json_file: str) -> None:
    """Convert CSV file to JSON with validation."""
    # Create CSV file
    csv_content = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com\n"
    Path(csv_file).write_text(csv_content)

    # Parse CSV and validate
    users = []
    with open(csv_file, "r") as f:
        reader = csv.DictReader(f)
        for row in reader:
            # Validate each field
            if not validate_email(row["email"]):
                continue

            age = parse_age(row["age"])
            if age is None:
                continue

            users.append({
                "name": row["name"],
                "age": age,
                "email": row["email"]
            })

    # Write JSON
    with open(json_file, "w") as f:
        json.dump(users, f, indent=2)

    print(f"Converted {len(users)} valid rows to {json_file}")


def main() -> None:
    """Main function."""
    csv_to_json("users.csv", "users.json")


if __name__ == "__main__":
    main()

