def read_numbers(file_path: Path) -> List[int]:
    numbers: List[int] = []
    try:
        with file_path.open("r", encoding="utf-8") as f:
            for line_num, line in enumerate(f, 1):
                try:
                    numbers.append(int(line.strip()))
                except ValueError:
                    print(f"Warning: Skipping invalid number on line {line_num} in '{file_path}': '{line.strip()}'")
    except FileNotFoundError:
        print(f"Error: Input file '{file_path}' not found.")
        raise
    except IOError as e:
        print(f"Error: Could not read file '{file_path}': {e}")
        raise
    return numbers

def process_numbers(numbers: List[int], threshold: int) -> List[int]:
    processed_results: List[int] = [
        n * n for n in numbers if (n * n) <= threshold
    ]
    return processed_results

def write_results(file_path: Path, results: List[int]) -> None:
    try:
        with file_path.open("w", encoding="utf-8") as f:
            for item in results:
                f.write(f"{item}\n")
    except IOError as e:
        print(f"Error: Could not write to file '{file_path}': {e}")
        raise

def main() -> None:
