        type=str,
        help="Path to the input file containing numbers (one per line)."
    )
    parser.add_argument(
        "output_file",
        type=str,
        help="Path to the output file for processed results."
    )
    parser.add_argument(
        "--threshold",
        type=int,
        default=100,
        help="Only results (squared numbers) less than or equal to this threshold will be written. Default: 100."
    )

