from __future__ import annotations

import argparse
import json
import sys
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Iterable, List


@dataclass
class FileStats:
    path: Path
    lines: int
    words: int
    characters: int

    def to_dict(self) -> dict:
        data = asdict(self)
        data["path"] = str(self.path)
        return data


def gather_paths(inputs: Iterable[str], recursive: bool = False) -> List[Path]:
    paths: List[Path] = []
    for p in inputs:
        path = Path(p)
        if path.is_file():
            paths.append(path)
        elif path.is_dir():
            if recursive:
                paths.extend([f for f in path.rglob("*") if f.is_file()])
            else:
                paths.extend([f for f in path.iterdir() if f.is_file()])
        else:
            # allow globs or non-existing paths; try to expand as glob
            matches = list(Path().glob(p))
            if matches:
                paths.extend([m for m in matches if m.is_file()])
            else:
                raise FileNotFoundError(f"Path not found: {p}")
    # remove duplicates while preserving order
    seen = set()
    unique: List[Path] = []
    for p in paths:
        if p not in seen:
            seen.add(p)
            unique.append(p)
    return unique


def analyze_file(path: Path) -> FileStats:
    try:
        with path.open("r", encoding="utf-8", errors="replace") as fh:
            lines = 0
            words = 0
            chars = 0
            for line in fh:
                lines += 1
                chars += len(line)
                # simple word splitting on whitespace
                words += len(line.split())
    except Exception as exc:
        raise IOError(f"Failed to read {path}: {exc}") from exc
    return FileStats(path=path, lines=lines, words=words, characters=chars)


def format_text_report(stats: List[FileStats]) -> str:
    if not stats:
        return "No files analyzed."
    max_path = max(len(str(s.path)) for s in stats)
    header = f"{'Path'.ljust(max_path)}  Lines   Words  Chars"
    lines = [header, "-" * len(header)]
    for s in stats:
        lines.append(f"{str(s.path).ljust(max_path)}  {s.lines:5d}   {s.words:5d}  {s.characters:5d}")
    total_lines = sum(s.lines for s in stats)
    total_words = sum(s.words for s in stats)
    total_chars = sum(s.characters for s in stats)
    lines.append("-" * len(header))
    lines.append(f"{'TOTAL'.ljust(max_path)}  {total_lines:5d}   {total_words:5d}  {total_chars:5d}")
    return "\n".join(lines)


def parse_args(argv: Iterable[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Compute simple file statistics (lines, words, characters).")
    parser.add_argument("paths", nargs="+", help="Files or directories (globs supported).")
    parser.add_argument("-r", "--recursive", action="store_true", help="Recurse into directories.")
    parser.add_argument("-j", "--json", action="store_true", help="Output results as JSON.")
    parser.add_argument("-v", "--verbose", action="store_true", help="Show progress and warnings.")
    return parser.parse_args(list(argv) if argv is not None else None)


def main(argv: Iterable[str] | None = None) -> int:
    args = parse_args(argv)
    try:
        paths = gather_paths(args.paths, recursive=args.recursive)
    except FileNotFoundError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 2

    if not paths:
        print("No files to analyze.", file=sys.stderr)
        return 1

    stats: List[FileStats] = []
    for p in paths:
        try:
            if args.verbose:
                print(f"Analyzing: {p}", file=sys.stderr)
            stats.append(analyze_file(p))
        except Exception as exc:
            print(f"Warning: {exc}", file=sys.stderr)

    if args.json:
        out = [s.to_dict() for s in stats]
        print(json.dumps(out, ensure_ascii=False, indent=2))
    else:
        print(format_text_report(stats))

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

