StateType = Union[Green, Yellow, Red]
EventType = Union[Tick, Reset]

def transition(state: StateType, event: EventType) -> StateType:
    """
    Applies an event to the current state and returns the new state.
    """
    if isinstance(event, Tick):
        if isinstance(state, Green):
            if state.timer > 0:
                return Green(state.timer - 1)
            else:
                return Yellow(3)
        elif isinstance(state, Yellow):
            if state.timer > 0:
                return Yellow(state.timer - 1)
            else:
                return Red(10)
        elif isinstance(state, Red):
            if state.timer > 0:
                return Red(state.timer - 1)
            else:
                return Green(20)
    elif isinstance(event, Reset):
        # Reset always transitions to Green(20)
        return Green(20)
    # This branch should ideally be unreachable if all types are handled,
    # but mypy might require it for exhaustive checking on complex unions
    # or if an unexpected type were passed.
    # For this specific problem, it's covered by the above ifs.
    raise ValueError(f"Unknown state or event combination: {state}, {event}")


def show_state(state: StateType) -> str:
    """
    Returns a string representation of the given state.
    """
    if isinstance(state, Green):
        return f"GREEN ({state.timer}sec)"
    elif isinstance(state, Yellow):
        return f"YELLOW ({state.timer}sec)"
    elif isinstance(state, Red):
        return f"RED ({state.timer}sec)"
    raise ValueError(f"Unknown state type: {state}")

def main() -> None:
    """
