}

func mapTree(fn: int -> int, tree: Tree) -> Tree {
  match tree {
    Leaf(v) => Leaf(fn(v)),
    Node(left, v, right) =>
      Node(mapTree(fn, left), fn(v), mapTree(fn, right))
  }
}

func foldTree(fn: int -> int -> int, acc: int, tree: Tree) -> int {
  match tree {
    Leaf(v) => fn(acc)(v),
    Node(left, v, right) => {
      let accAfterLeft = foldTree(fn, acc, left);
      let accAfterVal = fn(accAfterLeft)(v);
      foldTree(fn, accAfterVal, right)
    }
  }
}

func treeToList(tree: Tree) -> List[int] {
