from dataclasses import dataclass
from typing import Callable, Union, List

@dataclass
class Leaf:
    value: int

@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'

Tree = Union[Leaf, Node]

def map_tree(fn: Callable[[int], int], tree: Tree) -> Tree:
    """
    Recursively applies a function to all integer values in the tree.
    Returns a new tree with transformed values.
    """
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    else:  # isinstance(tree, Node)
        return Node(map_tree(fn, tree.left), fn(tree.value), map_tree(fn, tree.right))

def fold_tree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    """
    Performs an in-order fold over the tree values.
    Combines all values using the provided function and an initial accumulator.
    """
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    else:  # isinstance(tree, Node)
        acc_left = fold_tree(fn, acc, tree.left)
        acc_val = fn(acc_left, tree.value)
        return fold_tree(fn, acc_val, tree.right)

def tree_to_list(tree: Tree) -> List[int]:
    """
    Performs an in-order traversal of the tree and returns its values as a list.
    """
    if isinstance(tree, Leaf):
        return [tree.value]
    else:  # isinstance(tree, Node)
        return tree_to_list(tree.left) + [tree.value] + tree_to_list(tree.right)

def tree_depth(tree: Tree) -> int:
    """
    Calculates the maximum depth of the tree.
    """
    if isinstance(tree, Leaf):
        return 1
    else:  # isinstance(tree, Node)
        return 1 + max(tree_depth(tree.left), tree_depth(tree.right))

def main() -> None:
    # Example tree:
    #       5
    #      / \
    #     3   8
    #    /   / \
    #   1   7   9
    # Note: Leaf(0) is used as a dummy for a missing right child of node 3
    tree: Tree = Node(
        Node(Leaf(1), 3, Leaf(0)),  # Left subtree: Node(3) with Leaf(1) as left and Leaf(0) as dummy right
        5,
        Node(Leaf(7), 8, Leaf(9))   # Right subtree: Node(8) with Leaf(7) as left and Leaf(9) as right
    )

    # 1. Original: Print in-order values [1, 3, 5, 7, 8, 9]
    # Filter out dummy 0 values from the list for display as per example
    original_values = [val for val in tree_to_list(tree) if val != 0]
    print(f"Original: {original_values}")

    # 2. Doubled: Map with lambda x: x * 2, print [2, 6, 10, 14, 16, 18]
    doubled_tree = map_tree(lambda x: x * 2, tree)
    doubled_values = [val for val in tree_to_list(doubled_tree) if val != 0]
    print(f"Doubled: {doubled_values}")

    # 3. Sum: Fold with lambda a, b: a + b starting with 0, print sum (33)
    # The fold function naturally handles 0s without affecting the sum.
    tree_sum = fold_tree(lambda a, b: a + b, 0, tree)
    print(f"Sum: {tree_sum}")

    # 4. Depth: Calculate tree depth (3)
    # The depth calculation includes dummy nodes in its path length.
    tree_max_depth = tree_depth(tree)
    print(f"Depth: {tree_max_depth}")

if __name__ == "__main__":
    main()

